// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of http.ServeMux.
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("GET "+options.BaseURL+"/domains", wrapper.ListDomains)
	m.HandleFunc("POST "+options.BaseURL+"/domains", wrapper.CreateDomain)
	m.HandleFunc("GET "+options.BaseURL+"/domains/{domain}", wrapper.GetDomain)
	m.HandleFunc("PATCH "+options.BaseURL+"/domains/{domain}", wrapper.UpdateDomain)
	m.HandleFunc("GET "+options.BaseURL+"/domains/{domain}/api-keys", wrapper.ListAPIKeys)
	m.HandleFunc("POST "+options.BaseURL+"/domains/{domain}/api-keys", wrapper.CreateAPIKey)
	m.HandleFunc("GET "+options.BaseURL+"/domains/{domain}/api-keys/{key_id}", wrapper.GetAPIKey)
	m.HandleFunc("PATCH "+options.BaseURL+"/domains/{domain}/api-keys/{key_id}", wrapper.RevokeAPIKey)
	m.HandleFunc("GET "+options.BaseURL+"/domains/{domain}/batches", wrapper.ListBatches)
	m.HandleFunc("POST "+options.BaseURL+"/domains/{domain}/batches", wrapper.CreateBatch)
	m.HandleFunc("GET "+options.BaseURL+"/domains/{domain}/batches/{batch_id}", wrapper.GetBatch)
	m.HandleFunc("GET "+options.BaseURL+"/domains/{domain}/batches/{batch_id}/deliveries", wrapper.ListDeliveries)
	m.HandleFunc("GET "+options.BaseURL+"/domains/{domain}/batches/{batch_id}/deliveries/{delivery_id}", wrapper.GetDelivery)
	m.HandleFunc("GET "+options.BaseURL+"/domains/{domain}/stats/aggregated", wrapper.GetAggregatedStats)
	m.HandleFunc("GET "+options.BaseURL+"/domains/{domain}/stats/events", wrapper.ListStatsEvents)
	m.HandleFunc("GET "+options.BaseURL+"/domains/{domain}/templates", wrapper.ListTemplates)
	m.HandleFunc("POST "+options.BaseURL+"/domains/{domain}/templates", wrapper.CreateTemplate)
	m.HandleFunc("DELETE "+options.BaseURL+"/domains/{domain}/templates/{template_id}", wrapper.DeleteTemplate)
	m.HandleFunc("GET "+options.BaseURL+"/domains/{domain}/templates/{template_id}", wrapper.GetTemplate)
	m.HandleFunc("PATCH "+options.BaseURL+"/domains/{domain}/templates/{template_id}", wrapper.UpdateTemplate)
	m.HandleFunc("GET "+options.BaseURL+"/health", wrapper.GetHealth)

	return m
}
